CREATE TABLE audit_logs (id SERIAL PRIMARY KEY, user_id INTEGER, user_email VARCHAR(255), action_type VARCHAR(100), table_name VARCHAR(100), record_id INTEGER, old_values JSONB, new_values JSONB, ip_address VARCHAR(50), user_agent VARCHAR(500), created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE access_logs (id SERIAL PRIMARY KEY, user_id INTEGER, action VARCHAR(255), resource_type VARCHAR(100), resource_id INTEGER, ip_address VARCHAR(50), success BOOLEAN, error_message TEXT, accessed_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE change_history (id SERIAL PRIMARY KEY, entity_type VARCHAR(100), entity_id INTEGER, field_name VARCHAR(255), old_value TEXT, new_value TEXT, changed_by VARCHAR(100), change_reason VARCHAR(255), changed_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE system_events (id SERIAL PRIMARY KEY, event_type VARCHAR(100), event_name VARCHAR(255), event_details JSONB, severity VARCHAR(50), created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE compliance_records (id SERIAL PRIMARY KEY, record_type VARCHAR(100), subject VARCHAR(255), description TEXT, regulatory_requirement VARCHAR(255), evidence_url VARCHAR(500), approved_by VARCHAR(100), approval_date DATE, expiry_date DATE);
